// Build a small dashboard document and a separately cached, flash-resident model image.
import {build} from 'esbuild';
import {readFile,writeFile} from 'node:fs/promises';
import {gzipSync} from 'node:zlib';
import {createHash} from 'node:crypto';
import {fileURLToPath} from 'node:url';
import {minify} from 'html-minifier-terser';
const directory = new URL('./',import.meta.url);
const bundle = await build({entryPoints:[fileURLToPath(new URL('web/app.js',directory))],bundle:true,minify:true,write:false,target:'es2020',legalComments:'inline'});
const image = await readFile(new URL('web/model-mask.png',directory));
const template = await readFile(new URL('web/preview.html',directory),'utf8');
const imagePath = '/inter_comms/model-' + createHash('sha256').update(image).digest('hex').slice(0,16) + '.png';
const combined = template.replace('/* INTER_COMMS_BRIDGE */',bundle.outputFiles[0].text.replaceAll('</script','<\\/script')).replace("modelImage.src = 'model-mask.png'", 'modelImage.src = ' + JSON.stringify(imagePath));
const html = await minify(combined,{collapseWhitespace:true,removeComments:true,minifyCSS:true,minifyJS:true});
const bytes = gzipSync(html,{level:9});
if (bytes.length + image.length > 256*1024) throw new Error('Dashboard and model exceed their 256 KiB asset budget.');
await writeFile(new URL('dashboard.html',directory),html);
// Keep both assets in flash; the content hash invalidates the browser cache when the model changes.
function flashArray(name, data) {
	const lines=[];
	for(let i=0;i<data.length;i+=24) lines.push('  '+[...data.subarray(i,i+24)].map(byte=>'0x'+byte.toString(16).padStart(2,'0')).join(','));
	return 'static const uint8_t '+name+'[] PROGMEM = {\n'+lines.join(',\n')+'\n};\n';
}
await writeFile(new URL('dashboard_generated.h',directory),'// Generated by build_ui.mjs; do not edit.\n#pragma once\n'+flashArray('INTER_COMMS_DASHBOARD',bytes)+flashArray('INTER_COMMS_MODEL',image)+'static const char INTER_COMMS_MODEL_PATH[] PROGMEM = '+JSON.stringify(imagePath)+';\n');
console.log('Glasslight dashboard: '+bytes.length+' compressed HTML bytes; '+image.length+' separately cached model bytes');
// AI: end
